#include <iostream>
#include <unordered_map>
#include <string>

int main() {
    std::unordered_map<std::string, int> scores;

    // We just want to check if Bob is in the map...
    if (scores["Bob"] == 0) {
        std::cout << "Bob has no score.\n";
    }

    // BUG: Bob is now permanently in the map with a score of 0!
    std::cout << "Map size: " << scores.size() << '\n'; // Prints 1
    return 0;
}

#include <iostream>
#include <unordered_map>
#include <string>

int main() {
    std::unordered_map<std::string, int> scores;

    // Correct way to check for existence:
    if (scores.find("Bob") == scores.end()) {
        std::cout << "Bob is not in the map.\n";
    }

    // Correct way to read when you know it exists:
    try {
        int val = scores.at("Alice"); 
    } catch (const std::out_of_range& e) {
        std::cout << "Alice not found!\n";
    }

    std::cout << "Map size: " << scores.size() << '\n'; // Prints 0
    return 0;
}
